t.script:
(function () {
    var pend = null;
    document.addEventListener('click', function (e) {
        var b = e.target.closest('.pl-del-btn');
        if (!b) { return; }
        pend = b.closest('form');
        document.getElementById('plDelName').textContent = b.getAttribute('data-nombre') || '';
        document.getElementById('plDelModal').style.display = 'flex';
    });
    window.plCloseDel = function () {
        document.getElementById('plDelModal').style.display = 'none';
        pend = null;
    };
    window.plDoDelete = function () {
        if (pend) { pend.submit(); }
    };
    document.getElementById('plDelModal').addEventListener('click', function (e) {
        if (e.target === this) { window.plCloseDel(); }
    });
})();

div.script:
function plToggleAuto(cb) {
    var w = document.getElementById('autoPubWrap');
    var d = document.getElementById('auto_publish_date');
    if (cb.checked) { w.style.display = 'flex'; if (d) { d.required = true; } }
    else { w.style.display = 'none'; if (d) { d.required = false; d.value = ''; } }
}

t.script:
function plFiltrarRecip(input) {
    var q = (input.value || '').trim().toLowerCase();
    var list = input.closest('.pl-recipients').querySelector('.pl-recip-list');
    var rows = list.querySelectorAll('.pl-recip-row');
    var visibles = 0;
    Array.prototype.forEach.call(rows, function (row) {
        var hit = row.getAttribute('data-name').indexOf(q) !== -1;
        row.style.display = hit ? '' : 'none';
        if (hit) { visibles++; }
    });
    var vacio = list.querySelector('.pl-recip-empty');
    if (vacio) { vacio.style.display = visibles ? 'none' : ''; }
}

div.script:
(function () {
    var body = document.getElementById('plPreciosBody');
    if (!body) { return; }
    var tpl = document.getElementById('plLineaTpl');
    var addBtn = document.getElementById('plAddLinea');
    var vacio = document.getElementById('plSinLineas');
    var errBox = document.getElementById('plPrecioErr');

    function acoplar(tr) {
        var presSel = tr.querySelector('.pl-pres');
        var talla = tr.querySelector('.pl-talla');
        if (!presSel || !talla) { return; }
        var canal = tr.querySelector('.pl-canal');
        var calidad = tr.querySelector('.pl-calidad');
        var unidad = tr.querySelector('.pl-unidad');
        var pres = presSel.value;
        var esEntero = pres === 'entero';
        unidad.value = esEntero ? '$ / Kg' : '$ / Lb';
        // La talla se filtra por la presentación elegida: solo se
        // ven (y se pueden elegir) las de esa presentación.
        var primeraTalla = null;
        Array.prototype.forEach.call(talla.options, function (o) {
            var vale = o.getAttribute('data-pres') === pres;
            o.hidden = !vale; o.disabled = !vale;
            if (vale && !primeraTalla) { primeraTalla = o; }
        });
        var tActual = talla.options[talla.selectedIndex];
        if (primeraTalla && (!tActual || tActual.disabled)) { talla.value = primeraTalla.value; }
        // Canal solo aplica a cola. Se deja siempre enviable (no
        // disabled) para no descuadrar las columnas del POST; en
        // entero se vacía y se bloquea visualmente.
        if (esEntero) {
            canal.value = ''; canal.classList.add('pl-off'); canal.setAttribute('tabindex', '-1');
        } else {
            canal.classList.remove('pl-off'); canal.removeAttribute('tabindex');
            if (!canal.value) { canal.value = 'directa'; }
        }
        // La calidad también depende de la presentación (entero:
        // A-B / C; cola: A / B).
        var primeraCal = null;
        Array.prototype.forEach.call(calidad.options, function (o) {
            var vale = o.getAttribute('data-pres') === pres;
            o.hidden = !vale; o.disabled = !vale;
            if (vale && !primeraCal) { primeraCal = o; }
        });
        var cActual = calidad.options[calidad.selectedIndex];
        if (primeraCal && (!cActual || cActual.disabled)) { calidad.value = primeraCal.value; }
    }
    function refrescarVacio() {
        if (vacio) { vacio.style.display = body.querySelector('.pl-linea') ? 'none' : ''; }
    }

    Array.prototype.forEach.call(body.querySelectorAll('.pl-linea'), acoplar);
    refrescarVacio();

    body.addEventListener('change', function (e) {
        if (e.target.classList.contains('pl-pres')) { acoplar(e.target.closest('.pl-linea')); }
    });
    body.addEventListener('click', function (e) {
        var b = e.target.closest('.pl-del-linea');
        if (b) { b.closest('.pl-linea').remove(); refrescarVacio(); }
    });
    addBtn.addEventListener('click', function () {
        var wrap = document.createElement('tbody');
        wrap.innerHTML = tpl.innerHTML.trim();
        var tr = wrap.querySelector('.pl-linea');
        body.appendChild(tr);
        acoplar(tr);
        refrescarVacio();
        var t = tr.querySelector('.pl-talla'); if (t) { t.focus(); }
    });

    // Antes de guardar: toda fila debe tener precio.
    var form = document.getElementById('plHeaderForm');
    if (form) {
        form.addEventListener('submit', function (e) {
            var faltan = false;
            Array.prototype.forEach.call(body.querySelectorAll('.pl-precio'), function (p) {
                if (p.value === null || p.value.trim() === '') { faltan = true; p.classList.add('is-invalid'); }
                else { p.classList.remove('is-invalid'); }
            });
            if (faltan) {
                e.preventDefault();
                if (errBox) { errBox.style.display = ''; errBox.scrollIntoView({behavior: 'smooth', block: 'center'}); }
            } else if (errBox) { errBox.style.display = 'none'; }
        });
    }
})();

